    public struct Quaternion
    {
        public float x, y, z, w;

        public Quaternion(float x, float y, float z, float w) { this.x = x; this.y = y; this.z = z; this.w = w; }

        public static Quaternion identity => new(0, 0, 0, 1);

        public Vector3 eulerAngles
        {
            get
            {
                float sinr_cosp = 2 * (w * x + y * z);
                float cosr_cosp = 1 - 2 * (x * x + y * y);
                float roll = MathF.Atan2(sinr_cosp, cosr_cosp);

                float sinp = 2 * (w * y - z * x);
                float pitch = MathF.Abs(sinp) >= 1 ? MathF.CopySign(MathF.PI / 2, sinp) : MathF.Asin(sinp);

                float siny_cosp = 2 * (w * z + x * y);
                float cosy_cosp = 1 - 2 * (y * y + z * z);
                float yaw = MathF.Atan2(siny_cosp, cosy_cosp);

                return new Vector3(roll * Mathf.Rad2Deg, pitch * Mathf.Rad2Deg, yaw * Mathf.Rad2Deg);
            }
        }

        public static Quaternion Euler(float x, float y, float z)
        {
            x *= Mathf.Deg2Rad * 0.5f;
            y *= Mathf.Deg2Rad * 0.5f;
            z *= Mathf.Deg2Rad * 0.5f;
            float sx = MathF.Sin(x), cx = MathF.Cos(x);
            float sy = MathF.Sin(y), cy = MathF.Cos(y);
            float sz = MathF.Sin(z), cz = MathF.Cos(z);
            return new Quaternion(
                sx * cy * cz + cx * sy * sz,
                cx * sy * cz - sx * cy * sz,
                cx * cy * sz + sx * sy * cz,
                cx * cy * cz - sx * sy * sz);
        }

        public static Quaternion Euler(Vector3 euler) => Euler(euler.x, euler.y, euler.z);

        public static Quaternion Lerp(Quaternion a, Quaternion b, float t) => LerpUnclamped(a, b, Mathf.Clamp01(t));

        public static Quaternion LerpUnclamped(Quaternion a, Quaternion b, float t)
        {
            float dot = a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
            float sign = dot < 0 ? -1f : 1f;
            var result = new Quaternion(
                a.x + t * (sign * b.x - a.x),
                a.y + t * (sign * b.y - a.y),
                a.z + t * (sign * b.z - a.z),
                a.w + t * (sign * b.w - a.w));
            float mag = MathF.Sqrt(result.x * result.x + result.y * result.y + result.z * result.z + result.w * result.w);
            return new Quaternion(result.x / mag, result.y / mag, result.z / mag, result.w / mag);
        }

        public static Vector3 operator *(Quaternion rotation, Vector3 point)
        {
            float rx = rotation.x * 2f, ry = rotation.y * 2f, rz = rotation.z * 2f;
            float xx = rotation.x * rx, yy = rotation.y * ry, zz = rotation.z * rz;
            float xy = rotation.x * ry, xz = rotation.x * rz, yz = rotation.y * rz;
            float wx = rotation.w * rx, wy = rotation.w * ry, wz = rotation.w * rz;
            return new Vector3(
                (1f - (yy + zz)) * point.x + (xy - wz) * point.y + (xz + wy) * point.z,
                (xy + wz) * point.x + (1f - (xx + zz)) * point.y + (yz - wx) * point.z,
                (xz - wy) * point.x + (yz + wx) * point.y + (1f - (xx + yy)) * point.z);
        }

        public static Quaternion operator *(Quaternion a, Quaternion b) => new(
            a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
            a.w * b.y + a.y * b.w + a.z * b.x - a.x * b.z,
            a.w * b.z + a.z * b.w + a.x * b.y - a.y * b.x,
            a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z);
    }

    public struct Matrix4x4
    {
        public float m00, m01, m02, m03;
        public float m10, m11, m12, m13;
        public float m20, m21, m22, m23;
        public float m30, m31, m32, m33;

        public static Matrix4x4 identity => new()
        {
            m00 = 1, m11 = 1, m22 = 1, m33 = 1
        };

        public static Matrix4x4 TRS(Vector3 pos, Quaternion rot, Vector3 scale)
        {
            var m = new Matrix4x4();
            float x2 = rot.x * 2, y2 = rot.y * 2, z2 = rot.z * 2;
            float xx = rot.x * x2, yy = rot.y * y2, zz = rot.z * z2;
            float xy = rot.x * y2, xz = rot.x * z2, yz = rot.y * z2;
            float wx = rot.w * x2, wy = rot.w * y2, wz = rot.w * z2;

            m.m00 = (1 - (yy + zz)) * scale.x; m.m01 = (xy - wz) * scale.y; m.m02 = (xz + wy) * scale.z; m.m03 = pos.x;
            m.m10 = (xy + wz) * scale.x; m.m11 = (1 - (xx + zz)) * scale.y; m.m12 = (yz - wx) * scale.z; m.m13 = pos.y;
            m.m20 = (xz - wy) * scale.x; m.m21 = (yz + wx) * scale.y; m.m22 = (1 - (xx + yy)) * scale.z; m.m23 = pos.z;
            m.m30 = 0; m.m31 = 0; m.m32 = 0; m.m33 = 1;
            return m;
        }

        public Vector3 MultiplyPoint3x4(Vector3 p) => new(
            m00 * p.x + m01 * p.y + m02 * p.z + m03,
            m10 * p.x + m11 * p.y + m12 * p.z + m13,
            m20 * p.x + m21 * p.y + m22 * p.z + m23);

        public Vector3 MultiplyPoint(Vector3 p)
        {
            float w = m30 * p.x + m31 * p.y + m32 * p.z + m33;
            var result = new Vector3(
                (m00 * p.x + m01 * p.y + m02 * p.z + m03) / w,
                (m10 * p.x + m11 * p.y + m12 * p.z + m13) / w,
                (m20 * p.x + m21 * p.y + m22 * p.z + m23) / w);
            return result;
        }

        public Vector3 MultiplyVector(Vector3 v) => new(
            m00 * v.x + m01 * v.y + m02 * v.z,
            m10 * v.x + m11 * v.y + m12 * v.z,
            m20 * v.x + m21 * v.y + m22 * v.z);

        public static Matrix4x4 operator *(Matrix4x4 a, Matrix4x4 b)
        {
            var r = new Matrix4x4();
            r.m00 = a.m00 * b.m00 + a.m01 * b.m10 + a.m02 * b.m20 + a.m03 * b.m30;
            r.m01 = a.m00 * b.m01 + a.m01 * b.m11 + a.m02 * b.m21 + a.m03 * b.m31;
            r.m02 = a.m00 * b.m02 + a.m01 * b.m12 + a.m02 * b.m22 + a.m03 * b.m32;
            r.m03 = a.m00 * b.m03 + a.m01 * b.m13 + a.m02 * b.m23 + a.m03 * b.m33;
            r.m10 = a.m10 * b.m00 + a.m11 * b.m10 + a.m12 * b.m20 + a.m13 * b.m30;
            r.m11 = a.m10 * b.m01 + a.m11 * b.m11 + a.m12 * b.m21 + a.m13 * b.m31;
            r.m12 = a.m10 * b.m02 + a.m11 * b.m12 + a.m12 * b.m22 + a.m13 * b.m32;
            r.m13 = a.m10 * b.m03 + a.m11 * b.m13 + a.m12 * b.m23 + a.m13 * b.m33;
            r.m20 = a.m20 * b.m00 + a.m21 * b.m10 + a.m22 * b.m20 + a.m23 * b.m30;
            r.m21 = a.m20 * b.m01 + a.m21 * b.m11 + a.m22 * b.m21 + a.m23 * b.m31;
            r.m22 = a.m20 * b.m02 + a.m21 * b.m12 + a.m22 * b.m22 + a.m23 * b.m32;
            r.m23 = a.m20 * b.m03 + a.m21 * b.m13 + a.m22 * b.m23 + a.m23 * b.m33;
            r.m30 = a.m30 * b.m00 + a.m31 * b.m10 + a.m32 * b.m20 + a.m33 * b.m30;
            r.m31 = a.m30 * b.m01 + a.m31 * b.m11 + a.m32 * b.m21 + a.m33 * b.m31;
            r.m32 = a.m30 * b.m02 + a.m31 * b.m12 + a.m32 * b.m22 + a.m33 * b.m32;
            r.m33 = a.m30 * b.m03 + a.m31 * b.m13 + a.m32 * b.m23 + a.m33 * b.m33;
            return r;
        }

        public Matrix4x4 inverse => Inverse(this);

        public static Matrix4x4 Inverse(Matrix4x4 m)
        {
            // Cramer's rule for 4x4
            float a2323 = m.m22 * m.m33 - m.m23 * m.m32;
            float a1323 = m.m21 * m.m33 - m.m23 * m.m31;
            float a1223 = m.m21 * m.m32 - m.m22 * m.m31;
            float a0323 = m.m20 * m.m33 - m.m23 * m.m30;
            float a0223 = m.m20 * m.m32 - m.m22 * m.m30;
            float a0123 = m.m20 * m.m31 - m.m21 * m.m30;
            float a2313 = m.m12 * m.m33 - m.m13 * m.m32;
            float a1313 = m.m11 * m.m33 - m.m13 * m.m31;
            float a1213 = m.m11 * m.m32 - m.m12 * m.m31;
            float a2312 = m.m12 * m.m23 - m.m13 * m.m22;
            float a1312 = m.m11 * m.m23 - m.m13 * m.m21;
            float a1212 = m.m11 * m.m22 - m.m12 * m.m21;
            float a0313 = m.m10 * m.m33 - m.m13 * m.m30;
            float a0213 = m.m10 * m.m32 - m.m12 * m.m30;
            float a0113 = m.m10 * m.m31 - m.m11 * m.m30;
            float a0312 = m.m10 * m.m23 - m.m13 * m.m20;
            float a0212 = m.m10 * m.m22 - m.m12 * m.m20;
            float a0112 = m.m10 * m.m21 - m.m11 * m.m20;

            float det = m.m00 * (m.m11 * a2323 - m.m12 * a1323 + m.m13 * a1223)
                      - m.m01 * (m.m10 * a2323 - m.m12 * a0323 + m.m13 * a0223)
                      + m.m02 * (m.m10 * a1323 - m.m11 * a0323 + m.m13 * a0123)
                      - m.m03 * (m.m10 * a1223 - m.m11 * a0223 + m.m12 * a0123);
            float invDet = 1f / det;

            var r = new Matrix4x4();
            r.m00 = invDet * (m.m11 * a2323 - m.m12 * a1323 + m.m13 * a1223);
            r.m01 = invDet * -(m.m01 * a2323 - m.m02 * a1323 + m.m03 * a1223);
            r.m02 = invDet * (m.m01 * a2313 - m.m02 * a1313 + m.m03 * a1213);
            r.m03 = invDet * -(m.m01 * a2312 - m.m02 * a1312 + m.m03 * a1212);
            r.m10 = invDet * -(m.m10 * a2323 - m.m12 * a0323 + m.m13 * a0223);
            r.m11 = invDet * (m.m00 * a2323 - m.m02 * a0323 + m.m03 * a0223);
            r.m12 = invDet * -(m.m00 * a2313 - m.m02 * a0313 + m.m03 * a0213);
            r.m13 = invDet * (m.m00 * a2312 - m.m02 * a0312 + m.m03 * a0212);
            r.m20 = invDet * (m.m10 * a1323 - m.m11 * a0323 + m.m13 * a0123);
            r.m21 = invDet * -(m.m00 * a1323 - m.m01 * a0323 + m.m03 * a0123);
            r.m22 = invDet * (m.m00 * a1313 - m.m01 * a0313 + m.m03 * a0113);
            r.m23 = invDet * -(m.m00 * a1312 - m.m01 * a0312 + m.m03 * a0112);
            r.m30 = invDet * -(m.m10 * a1223 - m.m11 * a0223 + m.m12 * a0123);
            r.m31 = invDet * (m.m00 * a1223 - m.m01 * a0223 + m.m02 * a0123);
            r.m32 = invDet * -(m.m00 * a1213 - m.m01 * a0213 + m.m02 * a0113);
            r.m33 = invDet * (m.m00 * a1212 - m.m01 * a0212 + m.m02 * a0112);
            return r;
        }

        public static Matrix4x4 Perspective(float fov, float aspect, float zNear, float zFar)
        {
            float rad = fov * Mathf.Deg2Rad;
            float tanHalf = MathF.Tan(rad * 0.5f);
            var m = new Matrix4x4();
            m.m00 = 1f / (aspect * tanHalf);
            m.m11 = 1f / tanHalf;
            m.m22 = -(zFar + zNear) / (zFar - zNear);
            m.m23 = -(2f * zFar * zNear) / (zFar - zNear);
            m.m32 = -1f;
            return m;
        }

        public static Matrix4x4 Ortho(float left, float right, float bottom, float top, float zNear, float zFar)
        {
            var m = new Matrix4x4();
            m.m00 = 2f / (right - left);
            m.m11 = 2f / (top - bottom);
            m.m22 = -2f / (zFar - zNear);
            m.m03 = -(right + left) / (right - left);
            m.m13 = -(top + bottom) / (top - bottom);
            m.m23 = -(zFar + zNear) / (zFar - zNear);
            m.m33 = 1f;
            return m;
        }
    }

    public static class Mathf
    {
        public const float PI = 3.14159274f;
        public const float Infinity = float.PositiveInfinity;
        public const float NegativeInfinity = float.NegativeInfinity;
        public const float Deg2Rad = PI / 180f;
        public const float Rad2Deg = 180f / PI;
        public const float Epsilon = 1.401298E-45f;

        [MethodImpl(MethodImplOptions.AggressiveInlining)] public static float Cos(float f) => MathF.Cos(f);
