### Task 11: Extract Gameplay.unity Scene Parameters

**Files:**
- Create: `tools/extract_scene_params.py`
- Output: `BetterArc.Godot/scene_params.json`

- [ ] **Step 1: Write Python extraction script**

```python
#!/usr/bin/env python3
"""Extract Camera, RectTransform, and SerializeField values from Gameplay.unity YAML."""
import re
import json
import sys

def parse_unity_yaml(path):
    """Parse Unity YAML (has !u!N &ID headers) into a list of objects."""
    objects = []
    current = None
    with open(path, 'r', encoding='utf-8') as f:
        for line in f:
            if line.startswith('--- !u!'):
                if current:
                    objects.append(current)
                match = re.match(r'--- !u!(\d+) &(\d+)', line)
                current = {'_type_id': match.group(1), '_file_id': match.group(2), '_lines': []}
            elif current is not None:
                current['_lines'].append(line.rstrip())
    if current:
        objects.append(current)
    return objects

def extract_transform(obj):
    """Extract position, rotation, scale from Transform YAML lines."""
    result = {}
    lines = '\n'.join(obj['_lines'])
    for field in ['m_LocalPosition', 'm_LocalRotation', 'm_LocalScale']:
        m = re.search(rf'{field}:\s*\{{x: ([^,]+), y: ([^,]+), z: ([^,]+)(?:, w: ([^}}]+))?\}}', lines)
        if m:
            result[field] = {'x': float(m.group(1)), 'y': float(m.group(2)), 'z': float(m.group(3))}
            if m.group(4):
                result[field]['w'] = float(m.group(4))
    return result

def extract_camera(obj):
    """Extract camera parameters."""
    result = {}
    lines = '\n'.join(obj['_lines'])
    for field, key in [('field of view', 'fov'), ('near clip plane', 'near'), ('far clip plane', 'far'),
                        ('orthographic size', 'orthoSize'), ('orthographic', 'isOrtho')]:
        m = re.search(rf'{field}: (.+)', lines)
        if m:
            result[key] = float(m.group(1)) if '.' in m.group(1) else int(m.group(1))
    return result

def extract_rect_transform(obj):
    """Extract RectTransform anchored position, size delta, anchors, pivot."""
    result = {}
    lines = '\n'.join(obj['_lines'])
    for field in ['m_AnchoredPosition', 'm_SizeDelta', 'm_AnchorMin', 'm_AnchorMax', 'm_Pivot']:
        m = re.search(rf'{field}:\s*\{{x: ([^,]+), y: ([^}}]+)\}}', lines)
        if m:
            result[field] = {'x': float(m.group(1)), 'y': float(m.group(2))}
    return result

def main():
    scene_path = sys.argv[1] if len(sys.argv) > 1 else 're/ArcCreate/Assets/Scenes/Gameplay.unity'
    objects = parse_unity_yaml(scene_path)

    output = {'cameras': [], 'transforms': [], 'rect_transforms': []}

    for obj in objects:
        type_id = obj['_type_id']
        if type_id == '4':  # Transform
            data = extract_transform(obj)
            if data:
                data['_file_id'] = obj['_file_id']
                output['transforms'].append(data)
        elif type_id == '20':  # Camera
            data = extract_camera(obj)
            if data:
                data['_file_id'] = obj['_file_id']
                output['cameras'].append(data)
        elif type_id == '224':  # RectTransform
            data = extract_rect_transform(obj)
            data['_file_id'] = obj['_file_id']
            if data:
                output['rect_transforms'].append(data)

    with open('BetterArc.Godot/scene_params.json', 'w') as f:
        json.dump(output, f, indent=2)

    print(f"Extracted: {len(output['cameras'])} cameras, {len(output['transforms'])} transforms, {len(output['rect_transforms'])} rect_transforms")

if __name__ == '__main__':
    main()
```

