using Godot;
using System.Collections.Generic;

namespace BetterArc.Integration
{
    public partial class GodotAudioBridge : Node
    {
        private AudioStreamPlayer _musicPlayer;
        private readonly Dictionary<string, AudioStream> _sfxCache = new();
        private readonly List<AudioStreamPlayer> _sfxPool = new();

        public override void _Ready()
        {
            _musicPlayer = new AudioStreamPlayer();
            AddChild(_musicPlayer);

            for (int i = 0; i < 8; i++)
            {
                var player = new AudioStreamPlayer();
                AddChild(player);
                _sfxPool.Add(player);
            }
        }

        public void LoadMusic(string path)
        {
            var stream = ResourceLoader.Load<AudioStream>(path);
            if (stream != null) _musicPlayer.Stream = stream;
        }

        public void PlayMusic() => _musicPlayer.Play();
        public void PauseMusic() => _musicPlayer.StreamPaused = true;
        public void ResumeMusic() => _musicPlayer.StreamPaused = false;
        public float GetMusicTime() => (float)_musicPlayer.GetPlaybackPosition();
        public void SetMusicTime(float time) => _musicPlayer.Seek(time);

        public void PlaySfx(string path)
        {
            if (!_sfxCache.TryGetValue(path, out var stream))
            {
                stream = ResourceLoader.Load<AudioStream>(path);
                if (stream != null) _sfxCache[path] = stream;
            }

            foreach (var player in _sfxPool)
            {
                if (!player.Playing)
                {
                    player.Stream = stream;
                    player.Play();
                    return;
                }
            }
        }
    }
}
