using Godot;
using System.Collections.Generic;

namespace BetterArc.Integration
{
    public partial class GodotInputBridge : Node
    {
        private readonly List<UnityEngine.Touch> _activeTouches = new();

        public override void _Input(InputEvent @event)
        {
            if (@event is InputEventScreenTouch touch)
            {
                if (touch.Pressed)
                {
                    _activeTouches.Add(new UnityEngine.Touch
                    {
                        fingerId = touch.Index,
                        position = new UnityEngine.Vector2(touch.Position.X, touch.Position.Y),
                        phase = UnityEngine.TouchPhase.Began
                    });
                }
                else
                {
                    _activeTouches.RemoveAll(t => t.fingerId == touch.Index);
                }
            }
            else if (@event is InputEventScreenDrag drag)
            {
                for (int i = 0; i < _activeTouches.Count; i++)
                {
                    if (_activeTouches[i].fingerId == drag.Index)
                    {
                        var t = _activeTouches[i];
                        t.position = new UnityEngine.Vector2(drag.Position.X, drag.Position.Y);
                        t.phase = UnityEngine.TouchPhase.Moved;
                        _activeTouches[i] = t;
                    }
                }
            }
        }

        public override void _Process(double delta)
        {
            // Update shim Input state
            // This allows ArcCreate's Input.touchCount / Input.GetTouch to work
        }

        public int TouchCount => _activeTouches.Count;
        public UnityEngine.Touch GetTouch(int index) => _activeTouches[index];
    }
}
