namespace UnityEngine
{
    public struct Rect
    {
        public float x, y, width, height;

        public Rect(float x, float y, float width, float height) { this.x = x; this.y = y; this.width = width; this.height = height; }
        public Rect(Vector2 position, Vector2 size) { x = position.x; y = position.y; width = size.x; height = size.y; }

        public float xMin { get => x; set { float xMax_ = xMax; x = value; width = xMax_ - x; } }
        public float yMin { get => y; set { float yMax_ = yMax; y = value; height = yMax_ - y; } }
        public float xMax { get => x + width; set => width = value - x; }
        public float yMax { get => y + height; set => height = value - y; }
        public Vector2 position { get => new(x, y); set { x = value.x; y = value.y; } }
        public Vector2 size { get => new(width, height); set { width = value.x; height = value.y; } }
        public Vector2 center => new(x + width / 2f, y + height / 2f);
        public Vector2 min => new(xMin, yMin);
        public Vector2 max => new(xMax, yMax);

        public bool Contains(Vector2 point) => point.x >= xMin && point.x < xMax && point.y >= yMin && point.y < yMax;
    }

    public struct Bounds
    {
        public Vector3 center;
        public Vector3 size;

        public Bounds(Vector3 center, Vector3 size) { this.center = center; this.size = size; }

        public Vector3 min => center - size * 0.5f;
        public Vector3 max => center + size * 0.5f;
        public Vector3 extents => size * 0.5f;
    }

    public struct Ray
    {
        public Vector3 origin;
        public Vector3 direction;

        public Ray(Vector3 origin, Vector3 direction) { this.origin = origin; this.direction = direction; }
        public Vector3 GetPoint(float distance) => origin + direction * distance;
    }

    public struct RangeInt
    {
        public int start;
        public int length;
        public RangeInt(int start, int length) { this.start = start; this.length = length; }
        public int end => start + length;
    }
