using System.Threading.Tasks;

namespace Cysharp.Threading.Tasks
{
    public struct UniTask
    {
        private readonly Task _task;
        public UniTask(Task task) { _task = task; }

        public static UniTask CompletedTask => new(Task.CompletedTask);
        public static UniTask Delay(int millisecondsDelay) => new(Task.Delay(millisecondsDelay));
        public static UniTask Yield() => CompletedTask;
        public static UniTask WaitUntil(System.Func<bool> predicate) => new(Task.Run(async () => { while (!predicate()) await Task.Delay(1); }));

        public TaskAwaiter GetAwaiter() => new(_task);

        public struct TaskAwaiter : System.Runtime.CompilerServices.INotifyCompletion
        {
            private readonly Task _task;
            public TaskAwaiter(Task task) { _task = task; }
            public bool IsCompleted => _task?.IsCompleted ?? true;
            public void GetResult() => _task?.GetAwaiter().GetResult();
            public void OnCompleted(System.Action continuation) => _task?.ContinueWith(_ => continuation());
        }
    }

    public struct UniTask<T>
    {
        private readonly Task<T> _task;
        public UniTask(Task<T> task) { _task = task; }

        public TaskAwaiter GetAwaiter() => new(_task);

        public struct TaskAwaiter : System.Runtime.CompilerServices.INotifyCompletion
        {
            private readonly Task<T> _task;
            public TaskAwaiter(Task<T> task) { _task = task; }
            public bool IsCompleted => _task?.IsCompleted ?? true;
            public T GetResult() => _task != null ? _task.GetAwaiter().GetResult() : default;
            public void OnCompleted(System.Action continuation) => _task?.ContinueWith(_ => continuation());
        }
    }

    public struct UniTaskVoid
    {
        public void Forget() { }
    }

    public static class UniTaskExtensions
    {
        public static void Forget(this UniTask task) { }
        public static UniTask AsUniTask(this Task task) => new(task);
    }
}
